import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.v1TqQkD7.js";const g=JSON.parse('{"title":"Mutation Testing","description":"","frontmatter":{"title":"Mutation Testing","sourceFile":"guides/MUTATION-TESTING.md"},"headers":[],"relativePath":"guide/mutation-testing.md","filePath":"guide/mutation-testing.md"}'),r={name:"guide/mutation-testing.md"};function n(i,e,d,h,l,c){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="mutation-testing" tabindex="-1">Mutation Testing <a class="header-anchor" href="#mutation-testing" aria-label="Permalink to &quot;Mutation Testing&quot;">​</a></h1><p><strong>Implements:</strong> <code>TEST-07</code> — see <a href="./charter">CHARTER.md</a> Part 4 for the requirement and its status.</p><p>The deep-dive on the mutation tier. <a href="./testing#mutation">TESTING.md</a> places it among the other tiers and summarises it; this guide holds the detail the scripts and workflows link to: how the pull request run chooses what to mutate, why the nightly is sharded, how the floors were seeded, and where the scores stand.</p><p>Mutation testing measures whether the tests detect bugs, not whether they execute code. <a href="https://stryker-mutator.io/" target="_blank" rel="noreferrer">Stryker</a> makes small changes (&quot;mutants&quot;) to the source and checks whether any test fails. A test that fails kills the mutant. A mutant every test passes survived: a bug the suite would ship. A suite can reach 100% line coverage without asserting anything; mutation is the signal that it asserts. A tier that cannot fail manufactures confidence, and this is the tier that proves the others can fail.</p><p>Three runs, each held by a one-way ratchet:</p><table tabindex="0"><thead><tr><th>Run</th><th>Config</th><th>Scope</th><th>Floors</th></tr></thead><tbody><tr><td>Unit</td><td><code>config/mutation/stryker.config.mjs</code></td><td><code>src/core/**</code>, minus endpoints and interfaces</td><td><code>config/mutation/unit-thresholds.json</code>, 9 directories</td></tr><tr><td>BDD-only</td><td><code>config/mutation/stryker.bdd.config.mjs</code></td><td>all of <code>src/</code>, with the BDD suite as the only tests</td><td><code>config/mutation/bdd-thresholds.json</code>, 15 directories</td></tr><tr><td>Type</td><td><code>scripts/mutation/type-mutation.ts</code></td><td>the built <code>dist/**/*.d.ts</code></td><td><code>config/mutation/type-thresholds.json</code>, 6 entry points</td></tr></tbody></table><p>Type mutation is described in <a href="./testing#type-mutation">TESTING.md</a>; the rest of this guide covers the two Stryker runs.</p><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mutation</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # Full unit-suite run over the mutate scope</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mutation:ratchet</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # Score reports/mutation/mutation.json per directory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mutation:pr</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # What CI runs on a pull request: only your changed src/ files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mutation:fixture</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # The tier&#39;s self-test on a known-weak fixture</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mutation:bdd</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # BDD-only run (see below); one shard with BDD_MUTATION_SHARD=&lt;name&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mutation:bdd:merge</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Put the shard reports back together for the ratchet</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mutation:bdd:ratchet</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Score the BDD-only report per directory</span></span></code></pre></div><p>Reports are written to <code>reports/mutation/</code> (<code>mutation.html</code>, <code>mutation.json</code> and, with <code>--incremental</code>, <code>stryker-incremental.json</code>).</p><h2 id="where-mutation-testing-runs" tabindex="-1">Where mutation testing runs <a class="header-anchor" href="#where-mutation-testing-runs" aria-label="Permalink to &quot;Where mutation testing runs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Where</th><th>What</th><th>Gate</th></tr></thead><tbody><tr><td>Pull request (<code>mutation-pr.yml</code>)</td><td>Known-weak fixture, then the changed <code>src/</code> files in scope, incrementally</td><td>Advisory since 2026-09-27 (its own check, outside <code>ci-success</code>, until the release gate in ROADMAP.md puts it back): touched directories vs their floors, and the fixture. A cold run that times out warns</td></tr><tr><td>Nightly (<code>nightly-mutation.yml</code>)</td><td>Every file in scope (<code>--incremental --force</code>), one job per shard in <code>config/mutation/unit-shards.json</code></td><td>Fails the run: every directory vs its floor, scored on the merged report</td></tr><tr><td>Nightly, BDD-only matrix</td><td>All of <code>src/</code>, BDD step definitions only, one job per shard in <code>config/mutation/bdd-shards.json</code></td><td>Fails the run: every scored directory vs its floor in <code>config/mutation/bdd-thresholds.json</code></td></tr></tbody></table><p>The pull request job owns &quot;this change weakened the tests of the code it touched&quot;. The nightly owns everything a pull request cannot see: test-only changes, merges that interact, and directories no pull request touched.</p><h2 id="pull-requests" tabindex="-1">Pull requests <a class="header-anchor" href="#pull-requests" aria-label="Permalink to &quot;Pull requests&quot;">​</a></h2><p><code>npm run mutation:pr</code> (<code>scripts/mutation/mutation-pr.ts</code>) does, in order:</p><ol><li><strong>Base.</strong> <code>MUTATION_BASE_REF</code> (CI sets <code>HEAD^1</code>, the base tip of the pull request merge commit, with <code>fetch-depth: 2</code>), otherwise the merge base with <code>origin/master</code> or <code>master</code>. If none resolves, it fails closed (exit 2).</li><li><strong>Ratchet direction.</strong> <code>config/mutation/unit-thresholds.json</code> is compared with the base copy. Raising or adding a floor passes; lowering or removing one fails (exit 1). A missing or unparsable head file, or an unparsable base copy, fails closed. The only case with nothing to compare is a base commit that predates the file.</li><li><strong>Plan.</strong> <code>git diff --name-only --diff-filter=d &lt;base&gt; -- src/</code>, intersected with the <code>mutate</code> patterns in <code>config/mutation/stryker.config.mjs</code>. If nothing is left, the job summary says &quot;Skipped&quot; with the reason (no <code>src/</code> change, or only files outside the scope) and the step exits 0. The job still ran the thresholds check and the fixture, so it reports <code>success</code> honestly rather than being <code>skipped</code>, which <code>ci-success</code> counted as a failure while the job was inside it and will again once the release gate moves it back.</li><li><strong>Run.</strong> <code>stryker run config/mutation/stryker.config.mjs --incremental --mutate &lt;files&gt;</code>. The files are the changed ones plus any file in the same score directories that the restored nightly report cannot vouch for: absent from it, or with a source that has changed since. Stryker drops (rather than re-runs) stale mutants in files outside <code>--mutate</code>, so without this a directory score would silently shrink. With no restored report, every file in the touched directories is mutated from scratch: slower, never wrong. When the pull request changes or deletes a file under <code>tests/</code>, every reused file whose mutants that test covered in the restored report is mutated again and the run passes <code>--force</code>, because a score can only fall through a test that killed one of the file&#39;s mutants last night, and Stryker would otherwise reuse the old verdict as long as the test keeps its name (<a href="https://github.com/lgriffin/ESI.ts/issues/380" target="_blank" rel="noreferrer">#380</a>). A test the report does not know (a new file, or coverage it newly gained) can only raise a score, and the next nightly records that; re-mutating whole directories for it does not fit the job&#39;s time budget. A report without per-test coverage retests every reused file of the touched directories. A test-only pull request mutates the directories its tests reach: those the restored report shows the test covering, and for a test under <code>tests/tdd/</code> the directory its path mirrors; one the run can tie to no directory, or whose tests covered nothing in the report, is reported and skipped.</li><li><strong>Gate.</strong> Each touched directory is scored from the merged report (fresh results for changed code, nightly results for the rest) and fails if it is below its floor, or has no floor at all. The job summary lists the directory table, per-file scores for the changed files, and every surviving or uncovered mutant in them with its line, mutator and replacement. The HTML and JSON reports are uploaded as <code>mutation-pr-report</code>.</li></ol><p>Run it locally the same way; it diffs your working tree (committed or not) against the merge base with master:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mutation:pr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --concurrency</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span></span></code></pre></div><p>To reuse a nightly baseline locally, download the <code>mutation-report</code> artifact from the latest nightly and put its <code>stryker-incremental.json</code> in <code>reports/mutation/</code>. Stryker&#39;s incremental mode keys a mutant&#39;s result on the source and the covering tests&#39; names, so a test you strengthen under the same name would reuse the old Survived verdict on a plain <code>--incremental</code> run; <code>mutation:pr</code> passes <code>--force</code> for you when the diff touches <code>tests/</code>, and a direct <code>npm run mutation -- --incremental --force --mutate &lt;file&gt;</code> does the same by hand.</p><h3 id="when-there-is-no-baseline" tabindex="-1">When there is no baseline <a class="header-anchor" href="#when-there-is-no-baseline" aria-label="Permalink to &quot;When there is no baseline&quot;">​</a></h3><p><code>npm run mutation:pr:gate</code> runs the check under a deadline and decides what the outcome means, because two very different things look alike from outside: a run that measured a regression, and a run that measured nothing.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Outcome</th><th style="text-align:left;">With the nightly baseline</th><th style="text-align:left;">Without it</th></tr></thead><tbody><tr><td style="text-align:left;">A directory below its floor</td><td style="text-align:left;">blocks</td><td style="text-align:left;">blocks</td></tr><tr><td style="text-align:left;">The check cannot read its thresholds or base ref</td><td style="text-align:left;">blocks</td><td style="text-align:left;">blocks</td></tr><tr><td style="text-align:left;">The run does not finish in time</td><td style="text-align:left;">blocks</td><td style="text-align:left;"><strong>warns</strong></td></tr></tbody></table><p>A cold run mutates every file in the touched directories, not just the changed ones. #355 hit an eight-minute wall at 48% of 589 mutants, having killed every one it reached. Nothing was wrong with the change, and failing the pull request for it teaches people to read a red mutation job as noise. A timeout <em>with</em> the baseline restored still blocks: that run should only have had the changed files to mutate, so it is broken rather than slow.</p><p>The tier keeps a hard signal either way. <code>npm run mutation:fixture</code> runs first in the same job and fails when the known-weak fixture stops leaving survivors, so the gate can still fail even on a run that measures nothing. The policy is <code>classifyPrMutationRun</code> in <code>scripts/mutation/mutation-ratchet-core.ts</code>, pinned by <code>tests/tdd/mutation-ratchet/mutation-pr.test.ts</code>; <code>esi-23g.52</code> covers why a baseline can be missing in the first place.</p><h3 id="when-a-runner-is-reclaimed" tabindex="-1">When a runner is reclaimed <a class="header-anchor" href="#when-a-runner-is-reclaimed" aria-label="Permalink to &quot;When a runner is reclaimed&quot;">​</a></h3><p>GitHub-hosted runners intermittently drop a long job with <code>The runner has received a shutdown signal</code> and exit 143. On this repository: the unsharded BDD run at 30 minutes, the <code>core-pipeline</code> shard at 36, the <code>core-rest</code> shard at 45, while <code>core-rest</code> had itself finished at 59 minutes earlier the same day. (<code>core-pipeline</code> and <code>core-rest</code> are the names of BDD shards on 17 and 18 September 2026; they have since been split into the shards <code>config/mutation/bdd-shards.json</code> lists today.) It is random rather than a length limit, and nothing inside the job can defend against it: the runner goes, not the process.</p><p>Because the merge refuses an incomplete set, one reclaim costs every shard&#39;s score. Two things blunt that:</p><ul><li><strong>Shorter shards.</strong> A reclaim is roughly proportional to how long a job runs, so splitting the longest ones makes each loss smaller and each re-run cheaper. It does not make reclaims rarer.</li><li><strong><code>nightly-mutation-retry.yml</code>.</strong> On <code>workflow_run</code>, if the nightly finished as a failure on its first attempt, it re-runs the failed jobs once. <code>gh run rerun --failed</code> re-runs their dependents too, so the merge and the ratchet run again with the artifacts the surviving shards already uploaded, which persist across attempts of one run.</li></ul><p>It has to be a separate workflow: a job inside a run cannot re-run its own run. It is bounded to one extra attempt, because a shard that fails twice is not a reclaimed runner and the second failure should be read.</p><h3 id="why-the-unit-run-is-sharded" tabindex="-1">Why the unit run is sharded <a class="header-anchor" href="#why-the-unit-run-is-sharded" aria-label="Permalink to &quot;Why the unit run is sharded&quot;">​</a></h3><p>A single job over all of <code>src/core</code> took almost exactly two hours on 14, 15 and 16 September 2026 (119m40s, 120m08s, 119m26s) and then stopped finishing inside its 240-minute timeout. Nothing about the mutants changed: the unit suite grew from ~4,957 tests to 6,468, and with <code>coverageAnalysis: perTest</code> every added test slows every mutant. A nightly that never completes scores nothing and publishes no baseline, which is how the pull request gate came to mutate from scratch and time out as well (<code>esi-23g.52</code>).</p><p><code>config/mutation/unit-shards.json</code> splits <code>src/core</code> five ways, balanced by mutant count, and gives <code>src/sde</code> a shard of its own (Track S Run 2), so the SDE is scored, ratcheted and restored on its own. Counts are a property of the source and the mutator config rather than of the test suite, so these are the same numbers the BDD shards use:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Shard</th><th style="text-align:left;">Directories</th><th style="text-align:right;">Mutants</th></tr></thead><tbody><tr><td style="text-align:left;"><code>core-backoff</code></td><td style="text-align:left;">rateLimiter, circuitBreaker</td><td style="text-align:right;">594</td></tr><tr><td style="text-align:left;"><code>core-request-pipeline</code></td><td style="text-align:left;">requestPipeline</td><td style="text-align:right;">503</td></tr><tr><td style="text-align:left;"><code>core-root</code></td><td style="text-align:left;"><code>src/core</code> itself, and endpoints, which the globs exclude</td><td style="text-align:right;">453</td></tr><tr><td style="text-align:left;"><code>core-cache</code></td><td style="text-align:left;">cache, pagination, middleware</td><td style="text-align:right;">448</td></tr><tr><td style="text-align:left;"><code>core-support</code></td><td style="text-align:left;">logger, util</td><td style="text-align:right;">387</td></tr><tr><td style="text-align:left;"><code>sde</code></td><td style="text-align:left;"><code>src/sde</code>, ingestion included; the test-data factory excluded</td><td style="text-align:right;">1,317</td></tr></tbody></table><p>The core shards sum to 2,385, which is what the unsharded run over <code>src/core</code> instrumented when they were balanced; with <code>sde</code> the unsharded run instruments 3,702. The arithmetic is the check that nothing fell between them.</p><p><code>UNIT_MUTATION_SHARD=&lt;name&gt; npm run mutation</code> runs one, writing to <code>reports/mutation/shards/&lt;name&gt;/</code>. <code>npm run mutation:unit:merge</code> puts them back together for the ratchet and refuses a run with a shard missing, empty or overlapping another. <code>tests/tdd/mutation-ratchet/unitShards.test.ts</code> asserts the shards partition <code>src/core</code>, so a regrouping cannot drop a directory: orphaning <code>src/core/endpoints</code> fails 46 of its cases.</p><p>Each shard saves its own incremental file under <code>stryker-unit-shard-&lt;name&gt;-…</code>. A shard&#39;s file is a whole baseline for its own directories and knows nothing about the others, so the pull request job restores one only when it covers every file the run may mutate: <code>npm run mutation:pr:shard</code> plans the run before any baseline exists, names the one shard that claims all of those files (<code>baselineShardFor</code> in <code>scripts/mutation/mutation-merge-core.ts</code>), and <code>mutation-pr.yml</code> restores that shard&#39;s cache and copies it to <code>reports/mutation/stryker-incremental.json</code>. The common pull request touches one directory and gets a warm run whose timeout fails the job. A change that spans shards (say <code>src/core/RetryStrategy.ts</code> and <code>src/core/cache/</code>) restores nothing and runs cold, which warns rather than blocks on a timeout: restoring one shard there would claim a baseline the run only half has (<code>esi-23g.55</code>).</p><h3 id="the-incremental-baseline" tabindex="-1">The incremental baseline <a class="header-anchor" href="#the-incremental-baseline" aria-label="Permalink to &quot;The incremental baseline&quot;">​</a></h3><p>Each nightly shard runs <code>npm run mutation -- --incremental --force</code>: every mutant runs, and Stryker also writes an incremental file, which the job saves with <code>actions/cache/save</code> under <code>stryker-unit-shard-&lt;name&gt;-&lt;sha&gt;-&lt;run id&gt;</code>.</p><p><code>mutation-pr</code> restores the one shard&#39;s file that covers every file it will mutate, preferring the entry saved for the pull request&#39;s base commit, then the newest for that shard (see &quot;Why the unit run is sharded&quot; for how the shard is chosen). When no single shard covers the run, nothing is restored and the run is cold.</p><p>Caches written on <code>master</code> are readable by pull requests into <code>master</code>. Pull requests never save one.</p><p>Stryker reuses a result only when the mutant&#39;s code is unchanged and, for a killed mutant, its killing test is unchanged, or, for a survivor, no test was added. The older the baseline, the more mutants re-run: a one-day-old baseline on an active branch reused 51 of 169 mutants in <code>ETagCacheManager.ts</code>.</p><p>That rule has a blind spot in the local loop. Stryker treats a test as new only by its name, so strengthening an existing test (same name, a sharper assertion) does not invalidate a survivor it now kills: the next <code>--incremental</code> run still reports the mutant as Survived. In #375, <code>AsyncPaginationIterator.ts:17</code> (<code>body !== undefined</code> becoming <code>true</code>) stayed Survived after <code>toEqual([])</code> became <code>toHaveLength(0)</code>, although applying the mutant by hand showed the edited test killed it. It fails safe (the score reads low, never high), but it sends people after mutants that are already dead. Before you chase a survivor you believe a strengthened test kills, re-run that file with <code>--force</code>, which runs every mutant in the <code>--mutate</code> files and ignores the incremental results for them (<a href="https://github.com/lgriffin/ESI.ts/issues/380" target="_blank" rel="noreferrer">#380</a>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mutation</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --incremental</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mutate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/core/pagination/AsyncPaginationIterator.ts</span></span></code></pre></div><p>The nightly always runs with <code>--force</code>, so it clears such stale survivors every night. A pull request that only strengthens tests can still see its directory score read low until then, the same fail-safe way.</p><h3 id="ratchet-configmutationunit-thresholdsjson" tabindex="-1">Ratchet: <code>config/mutation/unit-thresholds.json</code> <a class="header-anchor" href="#ratchet-configmutationunit-thresholdsjson" aria-label="Permalink to &quot;Ratchet: \`config/mutation/unit-thresholds.json\`&quot;">​</a></h3><p>One floor per score directory: <code>src/core</code> for files directly in core, <code>src/core/&lt;sub&gt;</code> below it (the same <code>directoryOf</code> as the BDD ratchet in <code>scripts/mutation/mutation-ratchet-core.ts</code>). Values are Stryker&#39;s mutation score (detected / (detected + undetected)), rounded down to one decimal.</p><ul><li>A pull request that raises a directory&#39;s score leaves its floor alone; a follow-up raises it once two nightlies have measured the new tests (<code>npm run mutation:ratchet -- --update --also &lt;earlier report&gt;</code>, see &quot;Re-seeding&quot;). The pull request gate cannot prove the raise itself: it re-mutates only the changed <code>src/</code> files and keeps the nightly&#39;s results for the rest, so a directory improved by new tests alone is still scored on the survivors those tests kill. Re-mutating the whole directory instead does not fit the pull request budget for code that everything imports: on #374, <code>src/core/logger</code>&#39;s mutants are each covered by thousands of tests and the run timed out. State the new score in the follow-up&#39;s body in one line; ratchet bumps without a reason are how ratchet fatigue starts.</li><li>A floor never goes down. If a change truly has to lower one (for example, deleting dead code that only had killed mutants), that is a reviewed exception in its own pull request, and it fails <code>mutation-pr</code> there on purpose.</li><li>A new directory in scope must arrive with its floor; the failure message says which value to add.</li><li><code>npm run mutation:ratchet -- --update</code> (after a full <code>npm run mutation</code>) raises every floor to today&#39;s score and adds missing ones. It never lowers a floor.</li></ul><p><strong>Seeding.</strong> Each floor is the lower of two real runs: a full local run of this branch&#39;s base (<code>npm run mutation -- --incremental --force</code>, concurrency 4, 54 minutes) and the last nightly that produced a report (16 September 2026, <code>bc563d4d</code>, run 35067980626). They agree within two points for most directories but not all: <code>src/core/logger</code> scored 55.5% on the nightly and 33.3% locally, and <code>src/core/rateLimiter</code> 73% against 70.9%, mostly because a mutant that times out counts as detected, and how many time out depends on the machine. Taking the lower value means the first pull request to touch a directory is not failed by that spread. The nightly raises nothing on its own; floors move up only in reviewed pull requests.</p><p><strong>Re-seeding, 19 September 2026.</strong> The floors were raised from the first two complete sharded nightlies (runs 35352679266 and 35428381994), which differ only in a two-line change to <code>src/core/constants.ts</code>. Taking the lower of the two scores was not enough: 43 mutants changed status between the runs on the same code, 14 of them in <code>src/core/cache</code>, mostly a mutant that timed out on one runner and survived on the other. So each floor is the score of a report in which a mutant counts as detected only if <em>both</em> runs detected it. That is below either run&#39;s own score, which is the point: a third run on the same code cannot score below it unless a mutant neither run left alive survives. No floor was lowered; <code>src/core</code> stays at 81.8% where that rule gave 81.7%.</p><p><strong>Timing tests made deterministic (<a href="https://github.com/lgriffin/ESI.ts/issues/382" target="_blank" rel="noreferrer">#382</a>).</strong> The flips traced back to unit tests that measured real time: <code>setTimeout</code> sleeps before checking a cache entry had expired, circuit breaker cleanup that passed or not depending on whether a millisecond ticked between two calls, and retry and rate-limit waits that were slept through for real and then bounded loosely (<code>toBeGreaterThanOrEqual(40)</code> for a 50ms delay). Those tests in <code>tests/tdd/core</code> now run on Jest&#39;s fake clock (<code>jest.useFakeTimers()</code>, or <code>useFakeDate()</code> from <code>tests/tdd/helpers/fakeDate.ts</code> where the whole request pipeline runs and only <code>Date</code> should be frozen) or record <code>sleep()</code> calls with <code>Math.random</code> pinned, and each asserts the exact delay or boundary: an entry is fresh at its TTL and expired one millisecond later, a circuit is open at <code>resetTimeoutMs - 1</code> and half-open at <code>resetTimeoutMs</code>, a back-off is <code>[10, 20, 40]</code>, not &quot;positive&quot;. A mutant of one of those comparisons or delays is now killed by an assertion on every machine rather than by a timeout on a slow one. New tests of timing code follow the same rule (see <a href="./testing#time-and-randomness">TESTING.md</a>): no real sleeps, no <code>Date.now()</code> bounds.</p><p><strong>Re-seeding once the timing tests have landed.</strong> This step needs real nightlies and has not been done yet; the floors above are still the 19 September both-runs values. With the time-dependent mutants deterministic, two nightlies on the same <code>src/core</code> should agree mutant for mutant, and then <code>detectedByEveryRun</code> stops being what holds a floor down: seeding from one run with <code>npm run mutation:ratchet -- --update</code> gives the same floor as seeding from two with <code>--also</code>. To confirm that before relying on it:</p><ol><li>Wait for two complete sharded unit nightlies after the change, with no <code>src/core</code> change between them. Download each run&#39;s shard reports and merge them (<code>npm run mutation:unit:merge</code>) into two <code>mutation.json</code> files.</li><li>Run <code>npm run mutation:ratchet -- --update --also &lt;earlier report&gt;</code> against the later report, as on 19 September. Count the mutants whose status differs between the two reports; the issue&#39;s 43 is the number to beat, per directory as in the table below.</li><li>If the gap between each directory&#39;s score and its new floor is near zero, record the new floors and the flip count here in one line, and later re-seeds may use a single complete nightly without <code>--also</code>. Directories that still flip keep the two-run rule, and their flipping mutants are the next tests to make deterministic.</li></ol><h3 id="where-the-scores-stand" tabindex="-1">Where the scores stand <a class="header-anchor" href="#where-the-scores-stand" aria-label="Permalink to &quot;Where the scores stand&quot;">​</a></h3><p>The first two complete runs of the sharded unit matrix: 18 September 2026 (run 35352679266) and 19 September 2026 (run 35428381994). Five shards, 38 to 82 minutes each, merged into one report of 37 mutated files. The 18 September run was the first time <code>src/core</code> had been scored since 16 September: the unsharded job stopped finishing inside its 240-minute timeout as the suite grew.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Directory</th><th style="text-align:right;">18 Sept</th><th style="text-align:right;">19 Sept</th><th style="text-align:right;">Detected / valid (19 Sept)</th><th style="text-align:right;">Floor</th><th style="text-align:right;">Floor before</th></tr></thead><tbody><tr><td style="text-align:left;"><code>src/core</code></td><td style="text-align:right;">83.3%</td><td style="text-align:right;">83.3%</td><td style="text-align:right;">215/258</td><td style="text-align:right;">81.8%</td><td style="text-align:right;">81.8%</td></tr><tr><td style="text-align:left;"><code>src/core/cache</code></td><td style="text-align:right;">73.3%</td><td style="text-align:right;">70.1%</td><td style="text-align:right;">87/124</td><td style="text-align:right;">65.3%</td><td style="text-align:right;">53.3%</td></tr><tr><td style="text-align:left;"><code>src/core/circuitBreaker</code></td><td style="text-align:right;">77.7%</td><td style="text-align:right;">79.3%</td><td style="text-align:right;">100/126</td><td style="text-align:right;">77.7%</td><td style="text-align:right;">75.2%</td></tr><tr><td style="text-align:left;"><code>src/core/logger</code></td><td style="text-align:right;">59.2%</td><td style="text-align:right;">62.9%</td><td style="text-align:right;">17/27</td><td style="text-align:right;">55.5%</td><td style="text-align:right;">33.3%</td></tr><tr><td style="text-align:left;"><code>src/core/middleware</code></td><td style="text-align:right;">100%</td><td style="text-align:right;">100%</td><td style="text-align:right;">26/26</td><td style="text-align:right;">100%</td><td style="text-align:right;">92.3%</td></tr><tr><td style="text-align:left;"><code>src/core/pagination</code></td><td style="text-align:right;">73.9%</td><td style="text-align:right;">73.9%</td><td style="text-align:right;">88/119</td><td style="text-align:right;">73.9%</td><td style="text-align:right;">72.2%</td></tr><tr><td style="text-align:left;"><code>src/core/rateLimiter</code></td><td style="text-align:right;">78.3%</td><td style="text-align:right;">79.4%</td><td style="text-align:right;">213/268</td><td style="text-align:right;">77.9%</td><td style="text-align:right;">70.9%</td></tr><tr><td style="text-align:left;"><code>src/core/requestPipeline</code></td><td style="text-align:right;">77.6%</td><td style="text-align:right;">76.0%</td><td style="text-align:right;">184/242</td><td style="text-align:right;">75.2%</td><td style="text-align:right;">67.5%</td></tr><tr><td style="text-align:left;"><code>src/core/util</code></td><td style="text-align:right;">96.1%</td><td style="text-align:right;">95.4%</td><td style="text-align:right;">148/155</td><td style="text-align:right;">95.4%</td><td style="text-align:right;">95.3%</td></tr></tbody></table><p>A snapshot, not a source of truth: the live numbers are whatever the last nightly published, and this table is here to say where the floors sat relative to reality when the matrix first worked.</p><p><strong>The gap between a directory&#39;s score and its floor is now the flakiness of its mutants, not slack.</strong> Before the re-seeding, four directories sat 7 to 26 points above their floors, a measurement the ratchet was not holding: a change could have given back twenty points of <code>src/core/cache</code> and no gate would have noticed. What is left between score and floor is the mutants that are detected on one runner and not another. Killing those deterministically (fake timers and an exact assertion, rather than a timeout that depends on machine speed) is what lets a floor rise to the score. The timing tests named in #382 have moved to fake timers (see &quot;Timing tests made deterministic&quot; above); the re-seed that measures the effect is still to run.</p><p>Two caveats on comparing this table with an earlier one. A mutant that times out counts as detected, and how many time out depends on the machine, so a local run and a nightly disagree by a point or two on the same code (the seeding note above records <code>src/core/logger</code> at 55.5% nightly against 33.3% locally for exactly that reason), and two nightlies disagree too. And these are five separate shards merged, so each directory&#39;s score comes from the one shard that owns it rather than from a single process.</p><p>The BDD-only floors in <code>config/mutation/bdd-thresholds.json</code> come from the same two nights by the same rule. 19 September was the first run in which every BDD shard finished; on 18 September the <code>core-rest</code> shard (since split into <code>core-support</code> and <code>core-root</code>) lost a runner and the merge refused the incomplete set, but the seven shards that did finish still count, so a mutant any of them left alive counts as undetected. Most directories were therefore measured once, and BDD-only scores are low by design: the scenarios exercise behaviour through the transport seam, not every branch. The 15 floors today run from 0% (<code>src/schemas</code>, where a schema declaration has little for a scenario to kill) and 10.6% (<code>src/sde</code>) to 42.8% (<code>src/core/util</code>); <code>cat config/mutation/bdd-thresholds.json</code> lists them.</p><h3 id="the-known-weak-fixture" tabindex="-1">The known-weak fixture <a class="header-anchor" href="#the-known-weak-fixture" aria-label="Permalink to &quot;The known-weak fixture&quot;">​</a></h3><p><code>tests/mutation-fixture/weakClamp.ts</code> is a <code>clamp</code> function whose fixture test only checks an in-range value. <code>npm run mutation:fixture</code> mutates it with <code>config/mutation/stryker.fixture.config.mjs</code> and fails unless the report shows at least one killed mutant (the run can detect a fault), at least one survivor (a weak test is visible), and a ratchet failure for it against a 100% floor. <code>mutation-pr</code> runs it before the real run, so every pull request proves the pipeline can still go red. Do not strengthen that test. The last local run: 5 killed, 4 survived, 2 without coverage, score 45.4%, 15 seconds. Pointing the fixture&#39;s Jest <code>roots</code> at the original tree instead of the sandbox, the same mistake the module mapper used to make, turns that into 0 killed and 11 survived, and the check exits 1 with &quot;no fixture mutant was killed&quot;.</p><p><code>tests/tdd/mutation-ratchet/</code> holds the unit tests for the ratchet itself: a directory below its floor fails, a missing or unreadable thresholds file or base ref fails closed, a lowered or removed floor is rejected, a pull request with no in-scope <code>src/</code> change skips, and the plan widens to whole directories when the baseline cannot vouch for a file.</p><h3 id="sharding-the-bdd-only-run" tabindex="-1">Sharding the BDD-only run <a class="header-anchor" href="#sharding-the-bdd-only-run" aria-label="Permalink to &quot;Sharding the BDD-only run&quot;">​</a></h3><p>One job mutating all of <code>src/</code> against the BDD suite alone does not finish: 4,495 mutants, and the only attempt was killed at 30 minutes, which is why <code>config/mutation/bdd-thresholds.json</code> was empty for as long as it was. <code>nightly-mutation.yml</code> therefore runs one job per shard in <code>config/mutation/bdd-shards.json</code>; <code>BDD_MUTATION_SHARD=&lt;name&gt; npm run mutation:bdd</code> mutates that shard alone and writes <code>reports/mutation-bdd/shards/&lt;name&gt;/</code>.</p><p>A split run only means the same thing as the single run it replaces if nothing falls between the shards, so two checks hold it together:</p><ul><li><code>tests/tdd/mutation-ratchet/bddShards.test.ts</code> asserts the shards partition <code>src/</code>: every TypeScript file belongs to exactly one. <code>src/sde</code> has a shard of its own since Track S Run 2 (1,536 mutants), so the SDE&#39;s BDD scenarios are scored, ratcheted and restored apart from <code>rest</code>. A file claimed by none is never mutated and its directory&#39;s score quietly improves; a file claimed by two is counted twice. The exclusions in <code>config/mutation/stryker.bdd.config.mjs</code> are shared by every shard, so the union of the shards mutates exactly what the unsharded glob did.</li><li><code>npm run mutation:bdd:merge</code> (<code>scripts/mutation/mutation-merge-core.ts</code>) refuses to merge a run with a shard missing, a shard that mutated nothing, or two shards reporting one file. Without that, a shard whose job died would leave its directories scored on whatever else ran, which reads as a pass.</li></ul><p>Seed the floors from a completed run: dispatch the workflow with <code>seed_bdd_thresholds</code>, which prints and uploads <code>config/mutation/bdd-thresholds.json</code> raised to that run&#39;s scores. Nothing commits it; <code>--update</code> never lowers a floor.</p><h3 id="why-the-bdd-only-run-is-not-on-pull-requests" tabindex="-1">Why the BDD-only run is not on pull requests <a class="header-anchor" href="#why-the-bdd-only-run-is-not-on-pull-requests" aria-label="Permalink to &quot;Why the BDD-only run is not on pull requests&quot;">​</a></h3><p>Running the step definitions as the dry run for a <code>src/core/requestPipeline</code> change would take most of the 12-minute pull request budget on its own, and there is no incremental baseline to restore until the nightly matrix has published one. Once it has, a pull request run scoped to <code>src/core/requestPipeline</code> is the natural next step.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li><strong>Instrumentation</strong>: Stryker parses all files matching the <code>mutate</code> glob and identifies possible mutations (2,385 in the unit scope when the shards were balanced on 18 September 2026; see &quot;Why the unit run is sharded&quot;).</li><li><strong>Dry run</strong>: Stryker runs the related tests once to establish a baseline and map which tests cover which code (<code>enableFindRelatedTests</code>).</li><li><strong>Mutation</strong>: For each mutant, Stryker modifies the source and runs only the tests that cover the changed code (<code>perTest</code> coverage analysis). The TypeScript checker discards mutants that do not compile first.</li><li><strong>Scoring</strong>: Each mutant is classified:</li></ol><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Killed</strong></td><td>A test failed: the mutation was detected</td></tr><tr><td><strong>Survived</strong></td><td>All tests passed: a potential blind spot</td></tr><tr><td><strong>Timeout</strong></td><td>A test timed out, likely an infinite loop; counts as detected</td></tr><tr><td><strong>NoCoverage</strong></td><td>No test executes this code path</td></tr><tr><td><strong>CompileError</strong></td><td>The TypeScript checker rejected it; not counted</td></tr><tr><td><strong>Ignored</strong></td><td>Excluded mutator (<code>StringLiteral</code>) or static code; not counted</td></tr></tbody></table><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Config files: <code>config/mutation/stryker.config.mjs</code> (unit suite, nightly and pull requests), <code>config/mutation/stryker.bdd.config.mjs</code> (BDD-only), <code>config/mutation/stryker.fixture.config.mjs</code> (known-weak fixture).</p><h3 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><p>The unit run mutates <code>src/core/**/*.ts</code> and <code>src/sde/**/*.ts</code> with these exclusions:</p><ul><li><code>src/core/endpoints/**</code>: endpoint definitions are data declarations, not logic</li><li>Interface-only files (<code>ILogger.ts</code>, <code>ICache.ts</code>, <code>IRateLimiter.ts</code>, <code>IRetryStrategy.ts</code>, <code>ICircuitBreaker.ts</code>, <code>IDeduplicator.ts</code>) and the <code>requestPipeline</code> barrel and dependency wiring</li><li><code>src/sde/SdeTestDataFactory.ts</code>: a test fixture shipped for consumers&#39; tests; mutating it would score the fixture, not the module</li></ul><p>Files NOT in scope (and why):</p><table tabindex="0"><thead><tr><th>Excluded</th><th>Reason</th></tr></thead><tbody><tr><td><code>src/clients/**</code></td><td>Thin delegation layers tested via BDD scenarios</td></tr><tr><td><code>src/schemas/**</code></td><td>Zod schema declarations, no branching logic</td></tr><tr><td><code>src/types/**</code></td><td>Type-only files, no runtime code</td></tr><tr><td><code>src/config/**</code></td><td>Configuration setup, not core logic</td></tr><tr><td><code>src/EsiClient.ts</code>, <code>src/EsiClientBuilder.ts</code></td><td>High-level orchestration tested via integration tests</td></tr><tr><td><code>*.generated.ts</code></td><td>Auto-generated from OpenAPI spec</td></tr></tbody></table><p>A pull request that changes only out-of-scope <code>src/</code> files skips the mutation step and names those files in the summary.</p><h3 id="thresholds" tabindex="-1">Thresholds <a class="header-anchor" href="#thresholds" aria-label="Permalink to &quot;Thresholds&quot;">​</a></h3><p>The unit config has no global <code>break</code>; the per-directory floors in <code>config/mutation/unit-thresholds.json</code> are the gate. <code>high: 80</code> and <code>low: 60</code> only colour the HTML report.</p><p>A directory is <code>src/&lt;area&gt;</code> for most of the tree and <code>src/core/&lt;sub&gt;</code> or <code>src/sde/&lt;sub&gt;</code> inside the core and the SDE, whose parts differ enough that one number would hide a weak one (<code>directoryOf</code> in <code>scripts/mutation/mutation-ratchet-core.ts</code>). The SDE floors are provisional: <code>src/sde</code> and <code>src/sde/ingestion</code> were seeded on 2026-09-27 from a local unit run (87.6% and 73.8%, 1,317 mutants, 4 minutes) minus two points, and the BDD-only pair from a local run of the <code>sde</code> BDD shard the same way (<code>src/sde</code> 22.6% so 20.6, up from the 10.6 the whole tree scored before its subdirectories were split out; <code>src/sde/ingestion</code> 0, because no scenario reaches ingestion until Track S Run 6 specifies it), until the nightly matrix re-seeds them; floors come from the nightly, never from a laptop. Fifteen SDE mutants crash the test runner rather than fail a test (a missing-file check removed, a transform recursing on itself) and count as <code>RuntimeError</code>, which no score counts.</p><h3 id="sandbox-and-module-resolution" tabindex="-1">Sandbox and Module Resolution <a class="header-anchor" href="#sandbox-and-module-resolution" aria-label="Permalink to &quot;Sandbox and Module Resolution&quot;">​</a></h3><p>Stryker runs tests in an isolated sandbox (<code>.stryker-tmp/sandbox-XXX/</code>) containing mutated source files. Since tests live outside the sandbox at <code>tests/</code>, a <code>moduleNameMapper</code> redirects relative imports like <code>../../../src/core/...</code>, and a bare <code>../../../src</code> (the package root), to the sandbox&#39;s mutated source:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">moduleNameMapper</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;^(?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./)+src(/.*)?$&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;rootDir&gt;/src$1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Without this, tests would import the original (un-mutated) source and every mutant would survive or show as &quot;NoCoverage&quot;. Before the root import was mapped, <code>tests/tdd/auth/index.test.ts</code> compared classes loaded from the sandbox with classes loaded from the original tree, and the nightly&#39;s dry run failed on it (17 September 2026).</p><h3 id="static-mutants" tabindex="-1">Static Mutants <a class="header-anchor" href="#static-mutants" aria-label="Permalink to &quot;Static Mutants&quot;">​</a></h3><p><code>ignoreStatic: true</code> is enabled. Static mutants are mutations in module-level code (e.g., default values, constant expressions) that are only executed once during module initialization. These are expensive to test (they require re-running ALL tests since every test loads the module) and represent only ~1% of mutants. They are reported as &quot;Ignored&quot; in the output.</p><h2 id="reading-the-report" tabindex="-1">Reading the Report <a class="header-anchor" href="#reading-the-report" aria-label="Permalink to &quot;Reading the Report&quot;">​</a></h2><p>The HTML report at <code>reports/mutation/mutation.html</code> shows:</p><ul><li><strong>Per-file scores</strong> with color coding (green ≥ 80%, yellow ≥ 60%, red &lt; 60%)</li><li><strong>Individual mutants</strong> with their status, the original code, and the mutation applied</li><li><strong>Covering tests</strong> for each mutant (which tests would need to kill it)</li></ul><p>Current per-directory floors are in <code>config/mutation/unit-thresholds.json</code>; <code>npm run mutation:ratchet</code> prints today&#39;s scores next to them.</p><h2 id="improving-the-score" tabindex="-1">Improving the Score <a class="header-anchor" href="#improving-the-score" aria-label="Permalink to &quot;Improving the Score&quot;">​</a></h2><p>When a mutant survives, it means changing that line doesn&#39;t break any test. To kill it:</p><ol><li>Open the HTML report (or the <code>mutation-pr</code> job summary) and find the survived mutant</li><li>Read what the mutation does (e.g., <code>a &gt; b</code> changed to <code>a &gt;= b</code>)</li><li>Write a test case where the original behavior and mutated behavior produce different results</li><li>Re-run the file with <code>--force</code> to confirm the mutant is killed (an <code>--incremental</code> run can keep reporting it as Survived when you strengthened an existing test rather than adding one; see &quot;The incremental baseline&quot;)</li><li>Raise the directory&#39;s floor in <code>config/mutation/unit-thresholds.json</code> to the new score, with a one-line reason in the pull request</li></ol><p>The weakest directories at seeding were <code>src/core/cache</code> (<code>ETagCacheManager.ts</code>), <code>src/core/logger</code> and <code>src/core/requestPipeline</code> (<code>statusHandling.ts</code>, <code>cachePolicy.ts</code>).</p><h2 id="runtime" tabindex="-1">Runtime <a class="header-anchor" href="#runtime" aria-label="Permalink to &quot;Runtime&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Run</th><th>Wall time</th></tr></thead><tbody><tr><td>Pull request, one-function change to <code>ETagCacheManager.ts</code>, local, concurrency 4, same-day baseline</td><td>1 min 9 s (169 mutants instrumented, 1 of 1,845 files mutated)</td></tr><tr><td>The same change against a one-day-old baseline (51 of 169 mutants reused)</td><td>2 min 22 s</td></tr><tr><td>Known-weak fixture, local</td><td>15 s</td></tr><tr><td>Known-weak fixture, GitHub runner</td><td>9 s</td></tr><tr><td>Pull request job on a GitHub runner with no cached baseline (the whole <code>src/core/cache</code> directory mutated)</td><td>5 min 12 s for the job, 4 min 41 s for the mutation step</td></tr><tr><td>Full unit run, local, concurrency 4 (1,907 mutants, the seeding run of 16 September 2026)</td><td>54 min</td></tr><tr><td>Full unit run, nightly, unsharded (GitHub runner, concurrency 6), until 16 September 2026</td><td>about 2 h, then no longer finished inside 240 min</td></tr><tr><td>Full unit run, nightly, five shards (18 and 19 September 2026)</td><td>38 to 82 min per shard</td></tr></tbody></table><p>The pull request step has a 30-minute deadline inside a 37-minute job. It was 8 minutes until #434: <code>src/core/ApiRequestHandler.ts</code> has 110 mutants, and a change to it re-tests about 70 of them even with a fresh baseline, because every test that covers a changed line invalidates the mutants it reaches. At about 7 s a mutant on two test runners, plus 30 s per timeout, one such run reached 54 of 69 at a 15-minute deadline and 59 of 69 at 20, slowed further by test runners running out of memory and restarting. A change that invalidates most of a large directory (for example, a rewrite of <code>RateLimiter.ts</code> with no baseline) can still exceed 30; that fails the job rather than passing it.</p>`,100)])])}const p=t(r,[["render",n]]);export{g as __pageData,p as default};
